CREATE OR REPLACE FUNCTION public.firmaseguro_draft_administrative_recovery_guard()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE permission "FirmaSeguroDraftAdministrativeRecovery"%ROWTYPE; original "FirmaSeguroDraftDispatch"%ROWTYPE;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF OLD."status"='ABANDONED' AND NEW IS DISTINCT FROM OLD THEN
   RAISE EXCEPTION 'ABANDONED_DISPATCH_IMMUTABLE' USING ERRCODE='23514';
  END IF;
  IF NEW."status"='ABANDONED' AND OLD."status" IS DISTINCT FROM NEW."status" THEN
   SELECT * INTO permission FROM "FirmaSeguroDraftAdministrativeRecovery" WHERE "originalDispatchId"=OLD."id";
   IF NOT FOUND OR OLD."status"<>'UNCERTAIN' OR OLD."processUuid" IS NOT NULL OR OLD."expectedProcessUuid" IS NOT NULL
    OR permission."draftId"<>OLD."draftId" OR permission."documentHash"<>OLD."documentHash"
    OR permission."originalFingerprint"<>md5((to_jsonb(OLD)-'status'-'updatedAt')::text)
    OR (to_jsonb(NEW)-'status'-'updatedAt') IS DISTINCT FROM (to_jsonb(OLD)-'status'-'updatedAt')
    OR EXISTS(SELECT 1 FROM "FirmaSeguroDraftDispatchReceipt" WHERE "dispatchId"=OLD."id")
    OR EXISTS(SELECT 1 FROM "FirmaSeguroProcess" WHERE "draftId"=OLD."draftId")
   THEN RAISE EXCEPTION 'DRAFT_ADMINISTRATIVE_RECOVERY_NOT_AUTHORIZED' USING ERRCODE='23514'; END IF;
  END IF;
 ELSE
  IF NEW."status"='ABANDONED' THEN
   RAISE EXCEPTION 'DRAFT_ADMINISTRATIVE_INSERT_ABANDONED_FORBIDDEN' USING ERRCODE='23514';
  END IF;
  SELECT * INTO permission FROM "FirmaSeguroDraftAdministrativeRecovery" WHERE "draftId"=NEW."draftId";
  IF FOUND THEN
   IF NEW."id"<>permission."replacementDispatchId" THEN
    -- Subsequent ordinary audited corrections require a confirmed source process;
    -- no new unlinked commercial send can bypass the single authorized reserve.
    IF NEW."expectedProcessUuid" IS NOT NULL AND EXISTS(
     SELECT 1 FROM "FirmaSeguroProcess" process
     JOIN "FirmaSeguroDraftDispatchReceipt" receipt ON receipt."processUuid"=process."processUuid"
     JOIN "FirmaSeguroDraftDispatch" acknowledged ON acknowledged."id"=receipt."dispatchId"
     WHERE process."processUuid"=NEW."expectedProcessUuid" AND process."draftId"=NEW."draftId"
      AND process."creditoId" IS NULL AND acknowledged."draftId"=NEW."draftId"
      AND (acknowledged."status"='AWAITING_SIGNATURE' OR
       (acknowledged."status"='FAILED_SAFE'
        AND upper(btrim(process."status")) IN('ABORTADA','ABORTADO','ABORTED','ANULADA','ANULADO','CANCELADA','CANCELADO','CANCELED','CANCELLED','DECLINADA','DECLINADO','DECLINED','EXPIRED','EXPIRADA','EXPIRADO','RECHAZADA','RECHAZADO','REJECTED','REVOKED')
        AND upper(btrim(COALESCE((SELECT reconciliation."providerStatus"
         FROM "FirmaSeguroDraftDispatchReconciliation" reconciliation
         WHERE reconciliation."dispatchId"=acknowledged."id" AND reconciliation."processUuid"=receipt."processUuid"
         ORDER BY reconciliation."id" DESC LIMIT 1),receipt."providerStatus"))) IN('ABORTADA','ABORTADO','ABORTED','ANULADA','ANULADO','CANCELADA','CANCELADO','CANCELED','CANCELLED','DECLINADA','DECLINADO','DECLINED','EXPIRED','EXPIRADA','EXPIRADO','RECHAZADA','RECHAZADO','REJECTED','REVOKED')))
    ) THEN RETURN NEW; END IF;
    RAISE EXCEPTION 'DRAFT_ADMINISTRATIVE_ALLOWANCE_CONSUMED' USING ERRCODE='23514';
   END IF;
   SELECT * INTO original FROM "FirmaSeguroDraftDispatch" WHERE "id"=permission."originalDispatchId";
   IF original."status"<>'ABANDONED' OR NEW."draftId"<>permission."draftId" OR NEW."status"<>'PREPARING'
    OR NEW."actorUserId"<>permission."actorUserId" OR NEW."actorName"<>permission."actorName"
    OR NEW."reason"<>'Envío del contrato de la solicitud a FirmaSeguro' OR NEW."expectedProcessUuid" IS NOT NULL
    OR NEW."processUuid" IS NOT NULL OR NEW."requestPayload" IS NOT NULL OR NEW."dispatchedAt" IS NOT NULL
    OR NEW."draftFolio" IS DISTINCT FROM original."draftFolio"
    OR NEW."sourcePayload" IS DISTINCT FROM original."updatedPayload"
    OR NEW."updatedPayload" IS DISTINCT FROM original."updatedPayload"
    OR NEW."draftPayload" IS DISTINCT FROM original."draftPayload"
    OR NEW."frozenCredit" IS DISTINCT FROM original."frozenCredit"
    OR NEW."documentBase64" IS DISTINCT FROM original."documentBase64"
    OR NEW."documentHash" IS DISTINCT FROM original."documentHash"
    OR NOT EXISTS(SELECT 1 FROM "CreditoBorrador" d WHERE d."id"=NEW."draftId" AND d."estado"='ABIERTO'
     AND d."creditoId" IS NULL AND d."currentStep" IN(3,4) AND d."payload"=original."updatedPayload"
     AND COALESCE(d."expiresAt",d."createdAt"+INTERVAL '15 days')>CURRENT_TIMESTAMP)
   THEN RAISE EXCEPTION 'DRAFT_ADMINISTRATIVE_REPLACEMENT_INVALID' USING ERRCODE='23514'; END IF;
  END IF;
 END IF;
 RETURN NEW;
END $$

CREATE OR REPLACE FUNCTION public.firmaseguro_draft_administrative_receipt_guard()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE reconciliation BOOLEAN;
BEGIN
 IF EXISTS(SELECT 1 FROM "FirmaSeguroDraftDispatch" WHERE "id"=NEW."dispatchId" AND "status"='ABANDONED') THEN
  RAISE EXCEPTION 'ABANDONED_DISPATCH_RECEIPT_FORBIDDEN' USING ERRCODE='23514';
 END IF;
 IF TG_TABLE_NAME='FirmaSeguroDraftDispatchReconciliation' THEN reconciliation:=true;
 ELSE reconciliation:=NEW."source"='provider_reconciliation'; END IF;
 IF EXISTS(SELECT 1 FROM "FirmaSeguroDraftAdministrativeRecovery" WHERE "replacementDispatchId"=NEW."dispatchId")
  AND reconciliation
  AND COALESCE(NEW."evidence"->>'kind','')<>'provider_tag' THEN
  RAISE EXCEPTION 'DRAFT_ADMINISTRATIVE_EXACT_TAG_REQUIRED' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$

